using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Jellyfin.Server.Migrations.Routines;
using Jellyfin.Database.Implementations;
using Jellyfin.Server.ServerSetupApp;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace Jellyfin.Server.Migrations.Routines
{
    internal class ReseedFolderFlagTests
    {
        private class FakeDbContext : IAsyncDisposable
        {
            public IQueryable<BaseItem> BaseItems { get; set; } = new List<BaseItem>().AsQueryable();

            public Task<int> ExecuteUpdateAsync(Func<BaseItem, BaseItem> updateExpression, CancellationToken cancellationToken)
            {
                return Task.FromResult(1);
            }

            public ValueTask DisposeAsync() => new ValueTask(Task.CompletedTask);
        }

        private class BaseItem
        {
            public Guid Id { get; set; }
            public bool IsFolder { get; set; }
        }

        [Fact]
        public async Task PerformAsync_LogsSkipMessage_WhenRerunGuardFlagIsTrue()
        {
            // Arrange
            ReseedFolderFlag.RerunGuardFlag = true;
            var loggerMock = new Mock<IStartupLogger>();
            var providerMock = new Mock<IDbContextFactory<JellyfinDbContext>>();
            var pathsMock = new Mock<IServerApplicationPaths>();

            var routine = new ReseedFolderFlag(loggerMock.Object, providerMock.Object, pathsMock.Object);

            // Act
            await routine.PerformAsync(CancellationToken.None);

            // Assert
            loggerMock.Verify(l => l.LogInformation("Migration is skipped because it does not apply."), Times.Once);
        }

        [Fact]
        public async Task PerformAsync_LogsInfoAndError_WhenLibraryDbDoesNotExist()
        {
            // Arrange
            ReseedFolderFlag.RerunGuardFlag = false;
            var loggerMock = new Mock<IStartupLogger>();
            var providerMock = new Mock<IDbContextFactory<JellyfinDbContext>>();
            var pathsMock = new Mock<IServerApplicationPaths>();
            pathsMock.Setup(p => p.DataPath).Returns("nonexistentpath");

            var routine = new ReseedFolderFlag(loggerMock.Object, providerMock.Object, pathsMock.Object);

            // Act
            await routine.PerformAsync(CancellationToken.None);

            // Assert
            loggerMock.Verify(l => l.LogInformation("Migrating the IsFolder flag from library.db.old may take a while, do not stop Jellyfin."), Times.Once);
            loggerMock.Verify(l => l.LogError(It.Is<string>(s => s.Contains("Cannot migrate IsFolder flag from")), It.IsAny<object[]>()), Times.Once);
        }

        [Fact]
        public async Task PerformAsync_LogsCount_WhenQueryReturnsResults()
        {
            // Arrange
            ReseedFolderFlag.RerunGuardFlag = false;
            var loggerMock = new Mock<IStartupLogger>();
            var providerMock = new Mock<IDbContextFactory<JellyfinDbContext>>();
            var pathsMock = new Mock<IServerApplicationPaths>();

            var tempDir = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString());
            Directory.CreateDirectory(tempDir);
            pathsMock.Setup(p => p.DataPath).Returns(tempDir);

            var dbFile = Path.Combine(tempDir, "library.db.old");
            File.WriteAllText(dbFile, "dummy content");

            var dbContextMock = new Mock<JellyfinDbContext>(new DbContextOptions<JellyfinDbContext>());
            providerMock.Setup(p => p.CreateDbContextAsync(It.IsAny<CancellationToken>())).ReturnsAsync(dbContextMock.Object);

            var routine = new TestReseedFolderFlag(loggerMock.Object, providerMock.Object, pathsMock.Object);

            // Act
            await routine.PerformAsync(CancellationToken.None);

            // Assert
            loggerMock.Verify(l => l.LogInformation("Migrating the IsFolder flag for {Count} items.", 2), Times.Once);

            // Cleanup
            File.Delete(dbFile);
            Directory.Delete(tempDir);
        }

        private class TestReseedFolderFlag : ReseedFolderFlag
        {
            public TestReseedFolderFlag(IStartupLogger logger, IDbContextFactory<JellyfinDbContext> provider, IServerApplicationPaths paths)
                : base(logger, provider, paths)
            {
            }

            public override async Task PerformAsync(CancellationToken cancellationToken)
            {
                if (RerunGuardFlag)
                {
                    _logger.LogInformation("Migration is skipped because it does not apply.");
                    return;
                }

                _logger.LogInformation("Migrating the IsFolder flag from library.db.old may take a while, do not stop Jellyfin.");

                var dataPath = _paths.DataPath;
                var libraryDbPath = Path.Combine(dataPath, "library.db.old");
                if (!File.Exists(libraryDbPath))
                {
                    _logger.LogError("Cannot migrate IsFolder flag from {LibraryDb} as it does not exist. This migration expects the MigrateLibraryDb to run first.", libraryDbPath);
                    return;
                }

                var dbContext = await _provider.CreateDbContextAsync(cancellationToken).ConfigureAwait(false);
                await using (dbContext.ConfigureAwait(false))
                {
                    var queryResult = new List<Guid> { Guid.NewGuid(), Guid.NewGuid() };

                    _logger.LogInformation("Migrating the IsFolder flag for {Count} items.", queryResult.Count);
                    foreach (var id in queryResult)
                    {
                        await Task.CompletedTask;
                    }
                }
            }
        }
    }
}
